//! The schema: a compile-time list of everything a world can hold, and the
//! type-level lists that make borrowing from it checkable.

use alloc::vec::Vec;
use core::marker::PhantomData;

use crate::component::Column;
use crate::relation::Edges;
use crate::{Component, Entity, Relation, World};

/// Everything a [`World`] can hold, fixed at compile time. Generated by
/// [`schema!`](crate::schema).
///
/// Code that works with any world names only what it uses, so the bounds
/// read as a capability list:
///
/// ```
/// # use weft::*;
/// # struct Pos(i32); impl<S: Schema> Component<S> for Pos {}
/// # struct Vel(i32); impl<S: Schema> Component<S> for Vel {}
/// # struct Frozen; impl<S: Schema> Component<S> for Frozen {}
/// fn thaw<S: Writes<Vel> + Reads<Frozen>>(world: &mut World<S>, entity: Entity) {
///     if world.has::<Frozen>(entity) {
///         if let Some(mut vel) = world.get_mut::<Vel>(entity) {
///             vel.0 = 0;
///         }
///     }
/// }
///
/// fn physics<S: Borrows<(&'static mut Pos, &'static Vel)>>(world: &mut World<S>) {
///     world.query_mut::<(&mut Pos, &Vel)>().for_each(|(mut pos, vel)| pos.0 += vel.0);
/// }
/// ```
pub trait Schema: Sized + 'static {
    #[doc(hidden)]
    type Columns: Columns<Self> + Default;
    #[doc(hidden)]
    type Relations: Relations<Self> + Default;
    #[doc(hidden)]
    type Resources: Default + 'static;
}

/// The schema lists the component `T`.
#[diagnostic::on_unimplemented(
    message = "`{T}` is not a component of `{Self}`",
    label = "`{Self}` does not list `{T}`",
    note = "add `{T}` to `components: [..]` in the `schema!` that defines `{Self}`"
)]
pub trait Reads<T>: Schema {
    #[doc(hidden)]
    type Index;
    #[doc(hidden)]
    fn column(columns: &Self::Columns) -> &Column<T>;
    #[doc(hidden)]
    fn column_mut(columns: &mut Self::Columns) -> &mut Column<T>;
}

/// The schema lists the component `T` as `mut`, so its values can be
/// changed in place.
#[diagnostic::on_unimplemented(
    message = "`{T}` is not mutable in `{Self}`",
    label = "`{Self}` does not list `{T}` as `mut`",
    note = "write `mut {T}` in `components: [..]` in the `schema!` that defines `{Self}`"
)]
pub trait Writes<T>: Reads<T> {}

/// The schema lists the relation `R`.
#[diagnostic::on_unimplemented(
    message = "`{R}` is not a relation of `{Self}`",
    label = "`{Self}` does not list `{R}`",
    note = "add `{R}` to `relations: [..]` in the `schema!` that defines `{Self}`"
)]
pub trait Links<R>: Schema {
    #[doc(hidden)]
    fn edges(relations: &Self::Relations) -> &Edges<R>;
    #[doc(hidden)]
    fn edges_mut(relations: &mut Self::Relations) -> &mut Edges<R>;
}

/// The schema lists the resource `T`, so it always exists.
#[diagnostic::on_unimplemented(
    message = "`{T}` is not a resource of `{Self}`",
    label = "`{Self}` does not list `{T}`",
    note = "add `{T}` to `resources: [..]` in the `schema!` that defines `{Self}`"
)]
pub trait Owns<T>: Schema {
    #[doc(hidden)]
    fn resource(resources: &Self::Resources) -> &T;
    #[doc(hidden)]
    fn resource_mut(resources: &mut Self::Resources) -> &mut T;
}

// ---------------------------------------------------------------- type-level lists
//
// Lists are nested pairs `(A, (B, (C, ())))` and positions are Peano numbers.

/// Position 0 in a type-level list.
pub struct Zero;

/// The position after `N`.
pub struct Succ<N>(PhantomData<fn() -> N>);

/// A slot whose column has been lent out mutably.
pub struct Taken;

/// The element at position `N`.
pub trait At<N> {
    /// The element's type.
    type Item;
    /// Borrows the element.
    fn at(&self) -> &Self::Item;
    /// Mutably borrows the element.
    fn at_mut(&mut self) -> &mut Self::Item;
}

impl<H, T> At<Zero> for (H, T) {
    type Item = H;

    fn at(&self) -> &H {
        &self.0
    }

    fn at_mut(&mut self) -> &mut H {
        &mut self.0
    }
}

impl<H, T: At<N>, N> At<Succ<N>> for (H, T) {
    type Item = T::Item;

    fn at(&self) -> &T::Item {
        self.1.at()
    }

    fn at_mut(&mut self) -> &mut T::Item {
        self.1.at_mut()
    }
}

/// One slot of a [`Loans`] list: a column that is still available
/// ([`Column`]), lent out shared ([`Shared`]), or lent out mutably ([`Taken`]).
pub trait Slot: 'static {
    /// The borrow held for this slot.
    type At<'w>;
}

impl<T: 'static> Slot for Column<T> {
    type At<'w> = &'w mut Column<T>;
}

/// A slot whose column has been lent out shared.
pub struct Shared<C>(PhantomData<C>);

impl<C: 'static> Slot for Shared<C> {
    type At<'w> = &'w C;
}

impl Slot for Taken {
    type At<'w> = Taken;
}

/// The state of every column during a query, as a type: which ones are
/// still available, lent out shared, or lent out mutably. `At<'w>` is the
/// matching list of actual borrows.
pub trait Loans: 'static {
    /// The borrows, one per slot.
    type At<'w>;
}

impl Loans for () {
    type At<'w> = ();
}

impl<H: Slot, T: Loans> Loans for (H, T) {
    type At<'w> = (H::At<'w>, T::At<'w>);
}

/// Lends the column at `N` mutably, leaving [`Taken`] behind, so nothing
/// else can borrow it. The type-level version of `&mut`.
#[diagnostic::on_unimplemented(
    message = "this query borrows a component mutably that it also borrows elsewhere",
    label = "a component in this query is already borrowed",
    note = "a `&mut T` term must be the only term that mentions `T`",
    note = "in code generic over the schema, state the query as a bound: `S: Borrows<(&'static mut A, &'static B)>`"
)]
pub trait LendMut<N>: Loans {
    /// What is lent.
    type Target: 'static;
    /// The list with the slot marked [`Taken`].
    type Rest: Loans;
    /// Splits the loan off the list.
    fn lend_mut<'w>(list: Self::At<'w>) -> (&'w mut Self::Target, <Self::Rest as Loans>::At<'w>);
}

impl<C: 'static, T: Loans> LendMut<Zero> for (Column<C>, T) {
    type Target = Column<C>;
    type Rest = (Taken, T);

    fn lend_mut<'w>((column, rest): Self::At<'w>) -> (&'w mut Column<C>, (Taken, T::At<'w>)) {
        (column, (Taken, rest))
    }
}

impl<H: Slot, T: LendMut<N>, N: 'static> LendMut<Succ<N>> for (H, T) {
    type Target = T::Target;
    type Rest = (H, T::Rest);

    fn lend_mut<'w>((head, tail): Self::At<'w>) -> (&'w mut T::Target, (H::At<'w>, <T::Rest as Loans>::At<'w>)) {
        let (target, rest) = T::lend_mut(tail);
        (target, (head, rest))
    }
}

/// Lends the column at `N` shared, leaving a [`Shared`] loan behind, so it
/// can be lent shared again but never mutably. The type-level version of `&`.
#[diagnostic::on_unimplemented(
    message = "this query reads a component that it also borrows mutably",
    label = "a component in this query is already borrowed mutably",
    note = "a `&mut T` term must be the only term that mentions `T`",
    note = "in code generic over the schema, state the query as a bound: `S: Borrows<(&'static mut A, &'static B)>`"
)]
pub trait Lend<N>: Loans {
    /// What is lent.
    type Target: 'static;
    /// The list with the slot marked [`Shared`].
    type Rest: Loans;
    /// Splits the loan off the list.
    fn lend<'w>(list: Self::At<'w>) -> (&'w Self::Target, <Self::Rest as Loans>::At<'w>);
}

impl<C: 'static, T: Loans> Lend<Zero> for (Column<C>, T) {
    type Target = Column<C>;
    type Rest = (Shared<Column<C>>, T);

    fn lend<'w>((column, rest): Self::At<'w>) -> (&'w Column<C>, (&'w Column<C>, T::At<'w>)) {
        let shared: &'w Column<C> = column;
        (shared, (shared, rest))
    }
}

impl<C: 'static, T: Loans> Lend<Zero> for (Shared<C>, T) {
    type Target = C;
    type Rest = (Shared<C>, T);

    fn lend<'w>(list: Self::At<'w>) -> (&'w C, (&'w C, T::At<'w>)) {
        (list.0, list)
    }
}

impl<H: Slot, T: Lend<N>, N: 'static> Lend<Succ<N>> for (H, T) {
    type Target = T::Target;
    type Rest = (H, T::Rest);

    fn lend<'w>((head, tail): Self::At<'w>) -> (&'w T::Target, (H::At<'w>, <T::Rest as Loans>::At<'w>)) {
        let (target, rest) = T::lend(tail);
        (target, (head, rest))
    }
}

/// Reads the column at `N` if it hasn't been lent out mutably.
#[diagnostic::on_unimplemented(
    message = "this component is borrowed mutably by the query, so the view cannot read it",
    label = "borrowed mutably by the query",
    note = "read it through the query instead, or collect what you need before `query_mut`"
)]
pub trait Peek<N>: Loans {
    /// What can be read.
    type Target: 'static;
    /// Borrows it.
    fn peek<'a>(list: &'a Self::At<'_>) -> &'a Self::Target;
}

impl<C: 'static, T: Loans> Peek<Zero> for (Column<C>, T) {
    type Target = Column<C>;

    fn peek<'a>(list: &'a Self::At<'_>) -> &'a Column<C> {
        list.0
    }
}

impl<C: 'static, T: Loans> Peek<Zero> for (Shared<C>, T) {
    type Target = C;

    fn peek<'a>(list: &'a Self::At<'_>) -> &'a C {
        list.0
    }
}

impl<H: Slot, T: Peek<N>, N: 'static> Peek<Succ<N>> for (H, T) {
    type Target = T::Target;

    fn peek<'a>(list: &'a Self::At<'_>) -> &'a T::Target {
        T::peek(&list.1)
    }
}

// ------------------------------------------------------- operations over all storages

/// The list of component columns of a schema. It doubles as the initial
/// [`Loans`] state: every column available.
pub trait Columns<S: Schema>: Loans {
    /// Borrows every column at once.
    fn refs(&mut self) -> Self::At<'_>;
    /// Runs [`Component::on_remove`] for every component `entity` has,
    /// without removing anything, so each hook sees the entity whole.
    fn on_remove_all(world: &mut World<S>, entity: Entity);
    /// Drops every component of `entity` without running hooks.
    fn discard(&mut self, entity: Entity);
}

impl<S: Schema> Columns<S> for () {
    fn refs(&mut self) {}

    fn on_remove_all(_: &mut World<S>, _: Entity) {}

    fn discard(&mut self, _: Entity) {}
}

impl<S, T, R> Columns<S> for (Column<T>, R)
where
    S: Reads<T>,
    T: Component<S>,
    R: Columns<S>,
{
    fn refs(&mut self) -> Self::At<'_> {
        (&mut self.0, self.1.refs())
    }

    fn on_remove_all(world: &mut World<S>, entity: Entity) {
        if world.has::<T>(entity) {
            T::on_remove(world, entity);
        }
        R::on_remove_all(world, entity);
    }

    fn discard(&mut self, entity: Entity) {
        self.0.remove(entity);
        self.1.discard(entity);
    }
}

/// The list of relation storages of a schema.
pub trait Relations<S: Schema>: 'static {
    /// Collects the entities that must be despawned along with `entity`.
    fn cascade(&self, entity: Entity, out: &mut Vec<Entity>);
    /// Removes every edge touching `entity`, running [`Relation::on_unrelate`].
    fn unrelate_all(world: &mut World<S>, entity: Entity);
    /// Drops every edge touching `entity` without running hooks.
    fn discard(&mut self, entity: Entity);
}

impl<S: Schema> Relations<S> for () {
    fn cascade(&self, _: Entity, _: &mut Vec<Entity>) {}

    fn unrelate_all(_: &mut World<S>, _: Entity) {}

    fn discard(&mut self, _: Entity) {}
}

impl<S, R, Rest> Relations<S> for (Edges<R>, Rest)
where
    S: Links<R>,
    R: Relation<S>,
    Rest: Relations<S>,
{
    fn cascade(&self, entity: Entity, out: &mut Vec<Entity>) {
        if R::CASCADE {
            out.extend_from_slice(self.0.sources(entity));
        }
        self.1.cascade(entity, out);
    }

    fn unrelate_all(world: &mut World<S>, entity: Entity) {
        world.unrelate_all::<R>(entity);
        Rest::unrelate_all(world, entity);
    }

    fn discard(&mut self, entity: Entity) {
        self.0.discard(R::SYMMETRIC, entity);
        self.1.discard(entity);
    }
}

// ---------------------------------------------------------------------- macros

/// Declares a schema: every component, relation and resource a world can hold.
///
/// Components marked `mut` can be changed in place; the rest can only be
/// replaced wholesale with [`World::insert`]. Resources must implement
/// `Default` and always exist.
///
/// ```
/// use weft::*;
///
/// struct Pos(i32);
/// impl<S: Schema> Component<S> for Pos {}
///
/// struct Name(&'static str);
/// impl<S: Schema> Component<S> for Name {}
///
/// #[derive(Default)]
/// struct Frame(u64);
///
/// schema! {
///     struct Game {
///         components: [mut Pos, Name],
///         relations: [ChildOf],
///         resources: [Frame],
///     }
/// }
///
/// let mut world = World::<Game>::new();
/// let e = world.spawn((Pos(0), Name("a")));
/// world.resource_mut::<Frame>().0 += 1;
/// ```
///
/// Anything missing from the schema is a compile error where it's used:
///
/// ```compile_fail,E0277
/// # use weft::*;
/// # struct Pos(i32); impl<S: Schema> Component<S> for Pos {}
/// # struct Name(&'static str); impl<S: Schema> Component<S> for Name {}
/// schema! { struct Game { components: [Pos], relations: [], resources: [] } }
/// let world = World::<Game>::new();
/// world.query::<&Name>(); // `Name` is not a component of `Game`
/// ```
#[macro_export]
macro_rules! schema {
    (
        $(#[$meta:meta])*
        $vis:vis struct $name:ident {
            components: [$($components:tt)*] $(,)?
            relations: [$($relation:ty),* $(,)?] $(,)?
            resources: [$($resource:ty),* $(,)?] $(,)?
        }
    ) => {
        $(#[$meta])*
        $vis struct $name;
        $crate::__weft_components!(
            $name, $crate::internal::Zero, [], [$($relation),*], [$($resource),*], $($components)*
        );
        $crate::__weft_links!($name, $crate::internal::Zero, $($relation),*);
        $crate::__weft_owns!($name, $crate::internal::Zero, $($resource),*);
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __weft_components {
    ($name:ident, $index:ty, [$($all:ty),*], $rels:tt, $res:tt, mut $component:ty $(, $($rest:tt)*)?) => {
        $crate::__weft_components!(@reads $name, $index, $component);
        impl $crate::Writes<$component> for $name {}
        $crate::__weft_components!(
            $name, $crate::internal::Succ<$index>, [$($all,)* $component], $rels, $res, $($($rest)*)?
        );
    };
    ($name:ident, $index:ty, [$($all:ty),*], $rels:tt, $res:tt, $component:ty $(, $($rest:tt)*)?) => {
        $crate::__weft_components!(@reads $name, $index, $component);
        $crate::__weft_components!(
            $name, $crate::internal::Succ<$index>, [$($all,)* $component], $rels, $res, $($($rest)*)?
        );
    };
    ($name:ident, $index:ty, [$($all:ty),*], [$($relation:ty),*], [$($resource:ty),*], ) => {
        impl $crate::Schema for $name {
            type Columns = $crate::__weft_list!($($crate::internal::Column<$all>),*);
            type Relations = $crate::__weft_list!($($crate::internal::Edges<$relation>),*);
            type Resources = $crate::__weft_list!($($resource),*);
        }
    };
    (@reads $name:ident, $index:ty, $component:ty) => {
        impl $crate::Reads<$component> for $name {
            type Index = $index;

            fn column(
                columns: &<Self as $crate::Schema>::Columns,
            ) -> &$crate::internal::Column<$component> {
                $crate::internal::At::<$index>::at(columns)
            }

            fn column_mut(
                columns: &mut <Self as $crate::Schema>::Columns,
            ) -> &mut $crate::internal::Column<$component> {
                $crate::internal::At::<$index>::at_mut(columns)
            }
        }
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __weft_links {
    ($name:ident, $index:ty, ) => {};
    ($name:ident, $index:ty, $relation:ty $(, $rest:ty)*) => {
        impl $crate::Links<$relation> for $name {
            fn edges(
                relations: &<Self as $crate::Schema>::Relations,
            ) -> &$crate::internal::Edges<$relation> {
                $crate::internal::At::<$index>::at(relations)
            }

            fn edges_mut(
                relations: &mut <Self as $crate::Schema>::Relations,
            ) -> &mut $crate::internal::Edges<$relation> {
                $crate::internal::At::<$index>::at_mut(relations)
            }
        }
        $crate::__weft_links!($name, $crate::internal::Succ<$index>, $($rest),*);
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __weft_owns {
    ($name:ident, $index:ty, ) => {};
    ($name:ident, $index:ty, $resource:ty $(, $rest:ty)*) => {
        impl $crate::Owns<$resource> for $name {
            fn resource(resources: &<Self as $crate::Schema>::Resources) -> &$resource {
                $crate::internal::At::<$index>::at(resources)
            }

            fn resource_mut(resources: &mut <Self as $crate::Schema>::Resources) -> &mut $resource {
                $crate::internal::At::<$index>::at_mut(resources)
            }
        }
        $crate::__weft_owns!($name, $crate::internal::Succ<$index>, $($rest),*);
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __weft_list {
    () => { () };
    ($head:ty $(, $tail:ty)*) => { ($head, $crate::__weft_list!($($tail),*)) };
}
